export function findGymPath(equipment,a,b,gym,floor){const step=.5,start=[Math.round(a.x/step),Math.round((a.z+2)/step)],end=[Math.round(b.x/step),Math.round((b.z+2)/step)],key=p=>p.join(','),queue=[start],seen=new Map([[key(start),null]]);let cursor=0;while(cursor<queue.length){const p=queue[cursor++];if(key(p)===key(end)){const path=[];let current=p;while(current){path.push([current[0]*step,.12,current[1]*step]);current=seen.get(key(current))}return path.reverse()}for(const [dx,dz] of [[1,0],[-1,0],[0,1],[0,-1]]){const n=[p[0]+dx,p[1]+dz],x=n[0]*step,z=n[1]*step;if(x<-gym.width/2+1||x>gym.width/2-1||z<gym.minZ+1||z>gym.maxZ-1||seen.has(key(n)))continue;if(equipment.some(e=>e.floor===floor&&Math.abs(x-e.x)<1.65&&Math.abs(z-e.z)<1.65))continue;if(gym.obstacles.some(o=>(o.floor===undefined||o.floor===floor)&&Math.abs(x-o.x)<o.w/2+.15&&Math.abs(z-o.z)<o.d/2+.15))continue;seen.set(key(n),p);queue.push(n)}}return []}
